fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let n=["NullPointerException","IndexOutOfBoundsException","ArrayIndexOutOfBoundsException","IllegalStateException","RuntimeException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":n})}}}
fn state(book:&KmoBook,indices:&Value)->Value{let mut names=vec![];for i in 0..book.getLinkTable().borrow().getNumNames(){names.push(name(&mut book.getLinkTable().borrow().getNameRecord(i).unwrap().borrow_mut()));}let bs=book.getLinkTable().borrow().getAllExternalBookBlocks().unwrap();let external:Vec<_>=bs.borrow().iter().map(|b|block(b.as_deref())).collect();json!({"sst":snapshot(book,indices),"names":names,"external":external})}
struct OpenListener{book:Rc<KmoBook>,indices:Value,mode:usize,log:Rc<RefCell<Vec<Value>>>,calls:Cell<i32>}
impl KmoBookOpenEventListener for OpenListener{fn activeSheetDidFinishInitializing(&self){self.log.borrow_mut().push(state(&self.book,&self.indices));if self.mode==2{let old=self.calls.get();self.calls.set(old+1);if old==0{panic!("RuntimeException: observer first listener failure");}}}}
fn callbacks(book:&Rc<KmoBook>,input:&Value,p:&std::path::Path)->Value{let mut rows=vec![];for mode in 0..5{
    *book.getCellValueStore().borrow_mut()=KmoCellValueStore::KmoCellValueStore();let zip=ZipFile::from_path(p.join("zips").join(format!("source-{mode}.zip")).to_str().unwrap()).unwrap();let part=OpcrPackagePart::OpcrPackagePart(&zip,&zip.getEntry("xl/workbook.xml").unwrap());let styles=Rc::new(RefCell::new(StylesTable::StylesTable()));XlsxrStyles::open(book,None,&styles).unwrap();let part=Rc::new(RefCell::new(Some(part)));{let mut part=part.borrow_mut();let rels=part.as_mut().unwrap().getRelationships_mut().unwrap().unwrap();XlsxrSharedStrings::open(book,rels.getRelationship__rid_mut(Some("rIdS"))).unwrap();}for i in input["first"].as_array().unwrap(){XlsxrSharedStrings::onSheetStringIndex(i.as_i64().unwrap()as i32);}
    let events=Rc::new(RefCell::new(vec![]));let listener=Rc::new(OpenListener{book:book.clone(),indices:input["indices"].clone(),mode,log:events.clone(),calls:Cell::new(0)});let reader=XlsxrWorkbook::XlsxrWorkbook(book.clone(),None,if mode==1{None}else{Some(listener)},None);*reader.mBookPart.borrow_mut()=part.borrow_mut().take();*reader.mStylesTable.borrow_mut()=Some(styles);reader.setHasDefinedNames(true);UnifiedXmlReader::read(&mut std::io::Cursor::new(input["references"][mode].as_str().unwrap().as_bytes()),ExternalReferencesHandler::ExternalReferencesHandler(reader.clone()).asElementHandler()).unwrap();let before=state(book,&input["indices"]);let mut calls=vec![];for _ in 0..2{let mut r=call(||{reader.onFinishActiveSheet(999).unwrap();Value::Null});r["state"]=state(book,&input["indices"]);calls.push(r);}rows.push(json!({"before":before,"calls":calls,"listener":events.borrow().clone()}));
}json!(rows)}
struct ChangeListener{id:&'static str,group:Rc<KmoSheetChangeListenerGroup>,log:Rc<RefCell<Vec<String>>>,other:RefCell<Option<Rc<dyn KmoSheetChangeEventsListener>>>,mutation:i32,thrown:Cell<bool>}
impl ChangeListener{fn log(&self,s:&str){self.log.borrow_mut().push(format!("{}:{s}",self.id));}}
impl KmoSheetChangeEventsListener for ChangeListener{
    fn sheetDidFinishInitializing(&self){self.log("init");if self.mutation==1{self.group.remove(self.other.borrow().as_ref().unwrap());}if self.mutation==2&&!self.thrown.replace(true){panic!("RuntimeException: observer first init failure");}}
    fn sheetContentsDidFinishChanging(&self){self.log("contents");}
    fn sheetSettingsDidFinishChanging(&self){self.log("settings");}
    fn sheetSelectionChanged(&self){self.log("selection");}
    fn shapeContentChanged(&self,n:i32){self.log(&format!("shape:{n}"));}
}
fn groups(input:&Value)->Value{let mut out=vec![];for p in input["groups"].as_array().unwrap(){let g=Rc::new(KmoSheetChangeListenerGroup::new());let log=Rc::new(RefCell::new(vec![]));let a=Rc::new(ChangeListener{id:"a",group:g.clone(),log:log.clone(),other:RefCell::new(None),mutation:p["mutation"].as_i64().unwrap()as i32,thrown:Cell::new(false)});let b:Rc<dyn KmoSheetChangeEventsListener>=Rc::new(ChangeListener{id:"b",group:g.clone(),log:log.clone(),other:RefCell::new(None),mutation:0,thrown:Cell::new(false)});*a.other.borrow_mut()=Some(b.clone());g.add(a.clone());g.add(b.clone());let mut rows=vec![];for cmd in p["commands"].as_array().unwrap(){let mut r=call(||{match cmd.as_str().unwrap(){"init"=>g.sheetDidFinishInitializing(),"contents"=>g.sheetContentsDidFinishChanging(),"settings"=>g.sheetSettingsDidFinishChanging(),"selection"=>g.sheetSelectionChanged(),"start"=>g.startMergeEvents(),"finish"=>g.finishMergeEvents(),"addA"=>g.add(a.clone()),"removeB"=>g.remove(&b),"clear"=>g.clear(),"worker"=>{let g=g.clone();std::thread::spawn(move||{g.sheetContentsDidFinishChanging();g.chartContentChanged(51);}).join().unwrap();},s=>g.chartContentChanged(s.parse().unwrap())}Value::Null});r["log"]=json!(log.borrow().clone());rows.push(r);}g.clear();*a.other.borrow_mut()=None;out.push(rows);}json!(out)}
#[test]
fn original_android_workbook_callback_order_and_merge_events(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/workbook-callback-r0b48");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let actual=json!({"callbacks":callbacks(&api.book(),&input,&p),"groups":groups(&input)});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}compare(&actual,&java,"root");}
